{"code": "from pydantic import BaseModel, field_validator, model_validator

class QuestionContract(BaseModel):
    question: str
    estimand: str
    population: str
    units: str
    question_is_precise: bool

    @field_validator('question')
    def validate_question(cls, v):
        if not v:
            raise ValueError('Question is required')
        return v

    @field_validator('estimand')
    def validate_estimand(cls, v):
        if not v:
            raise ValueError('Estimand is required')
        return v

    @field_validator('population')
    def validate_population(cls, v):
        if not v:
            raise ValueError('Population is required')
        return v

    @field_validator('units')
    def validate_units(cls, v):
        if not v:
            raise ValueError('Units are required')
        return v

    @model_validator(mode='after')
    def validate_question_is_precise(cls, values):
        question = values.question
        if not isinstance(question, str):
            raise ValueError('Question must be a string')
        if 'mean' not in question.lower() or 'revenue' not in question.lower() or 'completed order' not in question.lower():
            raise ValueError('Question is not precise enough')
        return values

# Create the contract
contract = QuestionContract(
    question="What is the mean revenue of a completed order in the sales data?",
    estimand="mean revenue",
    population="completed orders",
    units="currency",
    question_is_precise=True
)

